// Regla: si n es par, lo dividís por 2; si es impar, lo multiplicás por 3 y sumás 1.
// Repetís hasta llegar a 1 y contás cuántos pasos hizo falta.
function pasos(n) {
  let cuenta = 0;
  while (n !== 1) {
    n = (n % 2 === 0) ? n / 2 : 3 * n + 1;
    cuenta = cuenta + 1;
  }
  return cuenta;
}

console.log(pasos(6), pasos(7), pasos(27));

